mapper.update:
UPDATE fbs_oauth_authorization_request
SET enterprise_id = #{request.tenantId},
    member_id = #{request.memberId},
    user_id = #{request.userId},
    principal_subject_digest = #{request.principalSubjectDigest},
    status = 'APPROVED',
    approved_at = #{request.approvedAt},
    version = version + 1
WHERE id = #{request.id}
  AND client_id = #{request.clientId}
  AND version = #{expectedVersion}
  AND status = 'PENDING'
  AND expires_at > #{request.approvedAt}

UPDATE fbs_oauth_authorization_request
SET status = 'CONSUMED',
    consumed_at = #{request.consumedAt},
    state_key_ref = NULL,
    state_nonce = NULL,
    state_ciphertext = NULL,
    version = version + 1
WHERE id = #{request.id}
  AND client_id = #{request.clientId}
  AND version = #{expectedVersion}
  AND status = 'APPROVED'
  AND expires_at >= #{request.consumedAt}

UPDATE fbs_oauth_authorization_code
SET status = 'USED', used_at = #{usedAt}, version = version + 1
WHERE id = #{codeId}
  AND version = #{expectedVersion}
  AND status = 'ACTIVE'
  AND expires_at > #{usedAt}

UPDATE fbs_oauth_authorization_code
SET status = 'REVOKED', revoked_at = #{revokedAt}, version = version + 1
WHERE id = #{codeId}
  AND version = #{expectedVersion}
  AND status = 'ACTIVE'

