SELECT *
FROM fbs_oauth_token_family
WHERE family_id = #{familyId}
  AND client_id = #{clientId}
FOR UPDATE

SELECT *
FROM fbs_oauth_token_family
WHERE enterprise_id = #{tenantId}
  AND member_id = #{memberId}
  AND user_id = #{userId}
  AND CAST(product_code AS BINARY) = CAST(#{productCode} AS BINARY)
  AND source_code = #{sourceCode}
  AND connector_code = #{connectorCode}
  AND status IN ('PENDING_BINDING', 'ACTIVE')
ORDER BY id
FOR UPDATE

mapper.update:
UPDATE fbs_oauth_token_family
SET binding_id = #{family.bindingId},
    binding_version = #{family.bindingVersion},
    status = 'ACTIVE',
    activated_at = #{family.activatedAt},
    version = version + 1
WHERE family_id = #{family.familyId}
  AND client_id = #{family.clientId}
  AND enterprise_id = #{family.tenantId}
  AND member_id = #{family.memberId}
  AND user_id = #{family.userId}
  AND resource_uri = #{family.resourceUri}
  AND version = #{expectedVersion}
  AND status = 'PENDING_BINDING'
  AND expires_at > #{family.activatedAt}

UPDATE fbs_oauth_token_family
SET current_refresh_generation = current_refresh_generation + 1,
    version = version + 1
WHERE family_id = #{familyId}
  AND version = #{expectedVersion}
  AND current_refresh_generation = #{expectedGeneration}
  AND status = 'ACTIVE'

