UPDATE fbs_oauth_token
SET status = 'USED', used_at = #{usedAt}, version = version + 1
WHERE id = #{tokenId}
  AND family_id = #{familyId}
  AND version = #{expectedVersion}
  AND token_type = 'REFRESH'
  AND status = 'ACTIVE'
  AND expires_at > #{usedAt}
